/**
 * Dashboard JavaScript for message management and donation actions.
 * Handles message editing, deletion, and donation navigation.
 * The code was mostly generated by AI based on user requirements
 * and for the learning purpose of AJAX.
 */

// Function for donating to animal
function donateToAnimal(animalSlug) {
    window.location.href = `/payments/donate/${animalSlug}/`;
}

// Message management functionality 
let currentPaymentId = null;

function editMessage(paymentId) {
    currentPaymentId = paymentId;
    
    // Fetch current message
    fetch(`/payments/message/${paymentId}/edit/`)
        .then(response => response.json())
        .then(data => {
            document.getElementById('modalTitle').textContent = 'Edit Your Message';
            document.getElementById('messageInput').value = data.message;
            document.getElementById('modalInfo').textContent = 
                `Donation to ${data.animal_name || 'an animal'} on ${data.created_at}`;
            updateCharCount();
            document.getElementById('messageModal').classList.remove('hidden');
        })
        .catch(error => {
            alert('Error loading message: ' + error);
        });
}

function addMessage(paymentId) {
    currentPaymentId = paymentId;
    
    document.getElementById('modalTitle').textContent = 'Add a Message';
    document.getElementById('messageInput').value = '';
    document.getElementById('modalInfo').textContent = 'Your message will be reviewed by an admin before appearing publicly.';
    updateCharCount();
    document.getElementById('messageModal').classList.remove('hidden');
}

// Delete message with custom modal
function deleteMessage(paymentId) {
    currentPaymentId = paymentId;
    document.getElementById('deleteModal').classList.remove('hidden');
}

// Close delete modal
function closeDeleteModal() {
    document.getElementById('deleteModal').classList.add('hidden');
    currentPaymentId = null;
}

// Confirm delete action
function confirmDelete() {
    const btn = document.getElementById('confirmDeleteBtn');
    
    btn.disabled = true;
    btn.innerHTML = 'Deleting...';
    
    fetch(`/payments/message/${currentPaymentId}/delete/`, {
        method: 'POST',
        headers: {
            'X-CSRFToken': getCookie('csrftoken'),
            'Content-Type': 'application/json',
        },
    })
    .then(response => response.json())
    .then(data => {
        if (data.success) {
            location.reload();
        } else {
            alert('Error deleting message');
            btn.disabled = false;
            btn.innerHTML = 'Delete';
            closeDeleteModal();
        }
    })
    .catch(error => {
        alert('Error deleting message: ' + error);
        btn.disabled = false;
        btn.innerHTML = 'Delete';
        closeDeleteModal();
    });
}

function saveMessage() {
    const message = document.getElementById('messageInput').value.trim();
    const btn = document.getElementById('saveMessageBtn');
    
    if (!message) {
        alert('Please enter a message');
        return;
    }
    
    btn.disabled = true;
    btn.innerHTML = 'Saving...';
    
    fetch(`/payments/message/${currentPaymentId}/edit/`, {
        method: 'POST',
        headers: {
            'X-CSRFToken': getCookie('csrftoken'),
            'Content-Type': 'application/json',
        },
        body: JSON.stringify({ message: message })
    })
    .then(response => response.json())
    .then(data => {
        if (data.success) {
            location.reload();
        } else {
            alert('Error saving message: ' + data.error);
            btn.disabled = false;
            btn.innerHTML = 'Save Message';
        }
    })
    .catch(error => {
        alert('Error saving message: ' + error);
        btn.disabled = false;
        btn.innerHTML = 'Save Message';
    });
}

function closeModal() {
    document.getElementById('messageModal').classList.add('hidden');
    currentPaymentId = null;
}

function updateCharCount() {
    const textarea = document.getElementById('messageInput');
    const charCount = document.getElementById('charCount');
    if (textarea && charCount) {
        charCount.textContent = `${textarea.value.length}/500`;
    }
}

// CSRF token helper
function getCookie(name) {
    let cookieValue = null;
    if (document.cookie && document.cookie !== '') {
        const cookies = document.cookie.split(';');
        for (let i = 0; i < cookies.length; i++) {
            const cookie = cookies[i].trim();
            if (cookie.substring(0, name.length + 1) === (name + '=')) {
                cookieValue = decodeURIComponent(cookie.substring(name.length + 1));
                break;
            }
        }
    }
    return cookieValue;
}

// Initialize when DOM is loaded
document.addEventListener('DOMContentLoaded', function() {
    // Set up character count for message input
    const messageInput = document.getElementById('messageInput');
    if (messageInput) {
        messageInput.addEventListener('input', updateCharCount);
        // Initial count
        updateCharCount();
    }
    
    // Close modals when clicking outside
    const messageModal = document.getElementById('messageModal');
    const deleteModal = document.getElementById('deleteModal');
    
    if (messageModal) {
        messageModal.addEventListener('click', function(e) {
            if (e.target === messageModal) {
                closeModal();
            }
        });
    }
    
    if (deleteModal) {
        deleteModal.addEventListener('click', function(e) {
            if (e.target === deleteModal) {
                closeDeleteModal();
            }
        });
    }
    
    // Close modals with Escape key
    document.addEventListener('keydown', function(e) {
        if (e.key === 'Escape') {
            if (!messageModal.classList.contains('hidden')) {
                closeModal();
            }
            if (!deleteModal.classList.contains('hidden')) {
                closeDeleteModal();
            }
        }
    });
});